15:func writeServerMessages(session *webSocketSession, remoteAddr string, readErr <-chan error) {
16:	ticker := time.NewTicker(time.Second / time.Duration(constants.ServerTickRate))
17:	defer ticker.Stop()
18:
19:	for {
20:		select {
21:		case err := <-readErr:
22:			context := session.sessionContext()
23:			logWebSocketReadClose(err, session.connectionTraceID, session.sessionID, context.RoomID, context.GamePlayerID)
24:			return
25:		case request := <-session.resyncRequests:
26:			if !writeResyncRequiredAndApply(session, request, remoteAddr) {
27:				return
28:			}
29:		case message := <-session.outbound:
30:			context := session.sessionContext()
31:			if !outbound.WriteServerMessage(session.conn, message, func(err error) {
32:				logWebSocketWriteClose(err, session.connectionTraceID, session.sessionID, context.RoomID, context.GamePlayerID)
33:			}) {
34:				return
35:			}
36:		case <-ticker.C:
37:			session.writeToolingProtocolMessage()
38:			if !writeGameplayLaneProtocolMessage(session, remoteAddr) {
39:				return
40:			}
41:		}
42:	}
43:}
44:
45:func writeGameplayLaneProtocolMessage(session *webSocketSession, remoteAddr string) bool {
46:	context := session.sessionContext()
47:	if context.Room == nil || context.GamePlayerID == "" {
48:		return true
49:	}
50:	gameplayContext := context.Room.GameplayContext()
51:	if gameplayContext.Game == nil {
52:		return true
53:	}
54:	resetRealtimeStateForContext(session, context, gameplayContext.MatchID)
55:
56:	result, err := realtime.BuildActiveRealtimeResultForGame(gameplayContext.Game, context.GamePlayerID, session.realtimeState)
57:	if err != nil {
58:		logging.Emit(observability.Request{
59:			Event: observability.EventNameOutboundPacketEncodeFailed,
60:			Context: observability.Context{
61:				TraceID:   session.connectionTraceID,
62:				SessionID: session.sessionID,
63:				RoomID:    context.RoomID,
64:				PlayerID:  context.GamePlayerID,
65:				MatchID:   gameplayContext.MatchID,
66:			},
67:			Fields: observability.Fields{
68:				"error_code":   "realtime_payload_build_failed",
69:				"failure_mode": "realtime_payload_build_failed",
70:			},
71:		})
72:		return false
73:	}
74:
75:	if !session.sessionContextMatches(context) || !context.Room.GameplayContextMatches(gameplayContext) {
76:		return true
77:	}
78:	nextRealtimeState := result.SessionState
79:	transport := session.webRTCTransportSnapshot()
80:	if transport == nil || !transport.Ready() {
81:		return true
82:	}
83:
84:	sentEventBatch := false
85:	for _, group := range groupEncodedRealtimeLanePackets(result.EncodedLanePackets) {
86:		blocked, valid := preflightRealtimeSendGroup(session, transport, group, context, gameplayContext.MatchID)
87:		if !valid {
88:			return false
89:		}
90:		if blocked {
91:			continue
92:		}
93:
94:		groupSent := true
95:		for _, encoded := range group.Packets {
96:			candidate := encoded.Candidate
97:			if len(encoded.Encoded) == 0 {
98:				continue
99:			}
100:			if !session.sessionContextMatches(context) || !context.Room.GameplayContextMatches(gameplayContext) {
101:				session.realtimeState = nextRealtimeState
102:				return true
103:			}
104:			lane := string(candidate.Lane())
105:			channelLabel, _ := webRTCChannelLabelForLane(lane)
106:			if err := transport.SendEncodedLaneJSON(lane, encoded.Encoded); err != nil {
107:				if errors.Is(err, ErrWebRTCChannelBackpressure) {
108:					logRealtimeBackpressure(session, transport, candidate, lane, channelLabel, context, gameplayContext.MatchID, 0)
109:					groupSent = false
110:					break
111:				}
112:				logging.Emit(observability.Request{
113:					Event: observability.EventNameGameServerWriteFailed,
114:					Context: observability.Context{
115:						TraceID:    session.connectionTraceID,
116:						SessionID:  session.sessionID,
117:						RoomID:     context.RoomID,
118:						PlayerID:   context.GamePlayerID,
119:						MatchID:    gameplayContext.MatchID,
120:						PacketType: candidate.PacketFamily(),
121:					},
122:					Fields: observability.Fields{
123:						"error_code":   "webrtc_lane_write_failed",
124:						"failure_mode": "webrtc_lane_write_failed",
125:						"lane":         lane,
126:						"transport":    "webrtc",
127:						"channel":      channelLabel,
128:					},
129:				})
130:				session.realtimeState = nextRealtimeState
131:				return false
132:			}
133:			session.observePacketWrite(lane, candidate.PacketFamily(), len(encoded.Encoded))
134:		}
135:		if !groupSent {
136:			continue
137:		}
138:
139:		for _, encoded := range group.Packets {
140:			realtime.CommitSuccessfulCandidate(&nextRealtimeState, encoded.Candidate)
141:			if encoded.Candidate.Kind() == realtime.RealtimeLaneCandidateKindEventBatch {
142:				sentEventBatch = true
143:			}
144:		}
145:		session.realtimeState = nextRealtimeState
146:	}
147:
148:	// Cadence and cohort state advance even when an individual hot lane is
149:	// backpressured. Only that lane's metadata and projection remain uncommitted.
150:	session.realtimeState = nextRealtimeState
151:	if sentEventBatch {
152:		drainActiveEventBatchAfterWrite(gameplayContext.Game, context.GamePlayerID, result.EventBatchEventIDs)
153:	}
154:	return true
155:}
