260:func resetRealtimeStateForContext(session *webSocketSession, context SessionContext, matchID string) {
261:	if session == nil || context.Room == nil || context.GamePlayerID == "" {
262:		return
263:	}
264:	if !session.realtimeState.IdentityMatches(context.GamePlayerID, matchID) {
265:		session.realtimeState = realtime.NewRealtimeSessionState(context.GamePlayerID, matchID)
266:	}
267:}
