269:func drainActiveEventBatchAfterWrite(gameInstance *game.Game, playerID string, eventIDs []string) []game.PendingPresentationEvent {
270:	if gameInstance == nil || len(eventIDs) == 0 {
271:		return nil
272:	}
273:	return gameInstance.DrainPendingPresentationEvents(playerID, eventIDs...)
274:}

