40:func BuildActiveRealtimeResult(snapshot game.GameplayPresentationSnapshot, state RealtimeSessionState) (ActiveRealtimeResult, error) {
41:	preparedState := state
42:	preparedState.AdvanceHotLaneTick()
43:	candidatePlan, err := assembleRealtimeLaneCandidates(snapshot, preparedState, &preparedState)
44:	if err != nil {
45:		return ActiveRealtimeResult{}, fmt.Errorf("assemble realtime lane candidates: %w", err)
46:	}
47:	candidatePlan.Candidates, err = ExpandRealtimeCandidateChunks(candidatePlan.Candidates)
48:	if err != nil {
49:		return ActiveRealtimeResult{}, fmt.Errorf("expand realtime candidate chunks: %w", err)
50:	}
51:
52:	records := make([]ScheduleRecord, 0, len(candidatePlan.Candidates))
53:	for i, candidate := range candidatePlan.Candidates {
54:		records = append(records, scheduleRecordForCandidate(i, candidate))
55:	}
56:	sendPlan := SelectSendPlan(records)
57:	selectedCandidates := IncludedRealtimeLaneCandidates(candidatePlan.Candidates, sendPlan.Included)
58:	encodedPackets := make(map[Lane][]byte, len(selectedCandidates))
59:	encodedBytes := make(map[Lane]int, len(selectedCandidates))
60:	encodedLanePackets := make([]EncodedRealtimeLanePacket, 0, len(selectedCandidates))
61:	for _, candidate := range selectedCandidates {
62:		encodedPacket, recordedBytes, err := encodeLanePacket(candidate)
63:		if err != nil {
64:			return ActiveRealtimeResult{}, fmt.Errorf("encode active candidate lane=%q family=%q: %w", candidate.Lane(), candidate.PacketFamily(), err)
65:		}
66:		if recordedBytes > 0 {
67:			encodedLanePackets = append(encodedLanePackets, EncodedRealtimeLanePacket{
68:				Candidate:    candidate,
69:				Encoded:      encodedPacket,
70:				EncodedBytes: recordedBytes,
71:			})
72:			if _, exists := encodedPackets[candidate.Lane()]; !exists {
73:				encodedPackets[candidate.Lane()] = encodedPacket
74:			}
75:			encodedBytes[candidate.Lane()] += recordedBytes
76:		}
77:	}
78:
79:	result := ActiveRealtimeResult{
80:		Snapshot:           snapshot,
81:		SessionState:       preparedState,
82:		Candidates:         candidatePlan.Candidates,
83:		SelectedCandidates: selectedCandidates,
84:		PlannedRecords:     records,
85:		SendPlan:           sendPlan,
86:		MetricRecord:       packetmetrics.PacketMetricRecord{},
87:		MetricSummaries:    nil,
88:		EncodedLanePackets: encodedLanePackets,
89:		EncodedPackets:     encodedPackets,
90:		EncodedBytes:       encodedBytes,
91:		EventBatchEventIDs: activeEventBatchEventIDs(snapshot.PendingEvents),
92:		Mode:               "active",
93:	}
94:	result.MetricRecord = result.SendPlan.Summary.ToPacketMetricRecord("active", LaneWorld)
95:	totalEncodedBytes := 0
96:	for _, recorded := range encodedLanePackets {
97:		totalEncodedBytes += recorded.EncodedBytes
98:	}
99:	result.TotalEncodedBytes = totalEncodedBytes
100:	if len(encodedBytes) > 0 {
101:		result.MetricRecord.Bytes = encodedBytes[LaneWorld]
102:	}
103:	result.MetricSummaries = ActiveLaneMetricRecords(result)
104:	return result, nil
105:}
