155:func ActiveLaneMetricRecords(result ActiveRealtimeResult) []packetmetrics.PacketMetricRecord {
156:	encodedPackets := encodedMetricPackets(result)
157:	records := make([]packetmetrics.PacketMetricRecord, 0, len(encodedPackets))
158:	for _, encoded := range encodedPackets {
159:		candidate := encoded.Candidate
160:		record := result.SendPlan.Summary.ToPacketMetricRecord(candidate.PacketFamily(), candidate.Lane())
161:		diagnostics := CandidateWriteDiagnosticsFor(candidate, result.SessionState, encoded.EncodedBytes)
162:		record.Bytes = encoded.EncodedBytes
163:		record.Channel = diagnostics.Channel
164:		record.EncodedBytes = diagnostics.EncodedBytes
165:		record.WorldHotCount = diagnostics.WorldHotCount
166:		record.ShipHotCount = diagnostics.ShipHotCount
167:		record.AsteroidHotCount = diagnostics.AsteroidHotCount
168:		record.BulletHotCount = diagnostics.BulletHotCount
169:		record.ShipOffloadedCount = diagnostics.ShipOffloadedCount
170:		record.AsteroidOffloadedCount = diagnostics.AsteroidOffloadedCount
171:		record.BulletOffloadedCount = diagnostics.BulletOffloadedCount
172:		record.ShipMode = string(diagnostics.ShipMode)
173:		record.AsteroidMode = string(diagnostics.AsteroidMode)
174:		record.BulletMode = string(diagnostics.BulletMode)
175:		record.Cadence = diagnostics.Cadence
176:		record.PacketOverTarget = diagnostics.PacketOverTarget
177:		record.PacketOverHardCap = diagnostics.PacketOverHardCap
178:		records = append(records, record)
179:	}
180:	return records
181:}
