206:func encodeLanePacketUnchecked(candidate RealtimeLaneCandidate) ([]byte, int, error) {
207:	packet, err := WireLanePacket(candidate)
208:	if err != nil {
209:		return nil, 0, err
210:	}
211:	if candidate.Lane() == LaneWorld || candidate.Lane() == LaneSession || candidate.Lane() == LaneOverlay || candidate.Lane() == LaneEvent || candidate.Lane() == LaneShips || candidate.Lane() == LaneAsteroids || candidate.Lane() == LaneBullets || candidate.Lane() == LaneShipsLifecycle || candidate.Lane() == LaneAsteroidsLifecycle || candidate.Lane() == LaneBulletsLifecycle {
212:		packet = CompactWirePacket(packet)
213:		if len(packet) == 0 {
214:			return nil, 0, fmt.Errorf("compact lane packet is empty")
215:		}
216:	}
217:	encoded, err := packetcodec.Encode(packet)
218:	if err != nil {
219:		return nil, 0, fmt.Errorf("json encode lane packet: %w", err)
220:	}
221:	return encoded, len(encoded), nil
222:}
223:
224:func encodeLanePacket(candidate RealtimeLaneCandidate) ([]byte, int, error) {
225:	encoded, recordedBytes, err := encodeLanePacketUnchecked(candidate)
226:	if err != nil {
227:		return nil, 0, err
228:	}
229:	if recordedBytes <= 0 {
230:		return nil, 0, fmt.Errorf("encoded lane packet is empty")
231:	}
232:	return encoded, recordedBytes, nil
233:}
234:
235:func laneFamilySummary(records []ScheduleRecord) string {
236:	if len(records) == 0 {
237:		return ""
238:	}
239:
240:	parts := make([]string, 0, len(records))
241:	for _, record := range records {
242:		parts = append(parts, string(record.Lane)+":"+record.PacketFamily)
243:	}
244:	return strings.Join(parts, ",")
245:}

