153:func nextHotLaneMetadata(world Metadata, state RealtimeSessionState, lane Lane) Metadata {
154:	laneState, synced := state.LaneState(lane)
155:	sequence := NextLaneSequence(laneState, synced)
156:	if worldState, ok := state.LaneState(LaneWorld); ok && worldState.BaselineID != "" {
157:		world.BaselineID = worldState.BaselineID
158:	}
159:	world.MatchID = state.MatchID
160:	world.Lane = lane
161:	world.Sequence = sequence
162:	world.SnapshotID = DeltaSnapshotID(lane, sequence)
163:	world.SnapshotKind = SnapshotKind("delta")
164:	world = world.WithChunk(0, 1)
165:	return world
166:}
