168:func shipHotProjectionIDs(projection ShipHotLaneProjection) map[string]bool {
169:	ids := make(map[string]bool, len(projection.Records))
170:	for _, record := range projection.Records {
171:		ids[record.ID] = true
172:	}
173:	return ids
174:}
