152:// CommitSuccessfulCandidate advances only the candidate that completed its
153:// transport write. Chunked candidates commit their projection on the final
154:// chunk so an incomplete same-sequence burst remains supersedable.
155:func CommitSuccessfulCandidate(state *RealtimeSessionState, candidate RealtimeLaneCandidate) {
156:	if state == nil {
157:		return
158:	}
159:	metadata, ok := candidate.Metadata()
160:	if !ok {
161:		return
162:	}
163:	persistedMetadata := AdvanceMetadataForSuccessfulWrite(candidate.Lane(), metadata)
164:	state.UpdateLane(candidate.Lane(), persistedMetadata)
165:	if !metadata.IsFinalChunk {
166:		return
167:	}
168:	projection, hasProjection := CandidateProjection(candidate)
169:	if hasProjection {
170:		state.StoreBaselineProjection(candidate.Lane(), projection)
171:	}
172:	if candidate.Kind() == RealtimeLaneCandidateKindFull {
173:		state.MarkBaselineReady(candidate.Lane())
174:	}
175:	if candidate.Lane() != LaneWorld || !hasProjection {
176:		return
177:	}
178:	world, ok := projection.(WorldWireFullPacket)
179:	if !ok {
180:		return
181:	}
182:	if candidate.Kind() == RealtimeLaneCandidateKindFull {
183:		seedHotLaneProjections(state, world)
184:		return
185:	}
186:	syncHotLaneProjectionMembership(state, world)
187:}

