34:			Lives:               player.Lives,
35:			RespawnCooldown:     player.RespawnCooldown,
36:			PrimaryWeaponID:     player.PrimaryWeaponID,
37:			PrimaryAmmoPolicy:   player.PrimaryAmmoPolicy,
38:			SecondaryWeaponID:   player.SecondaryWeaponID,
39:			SecondaryAmmoPolicy: player.SecondaryAmmoPolicy,
40:			SpawnX:              player.SpawnX,
41:			SpawnY:              player.SpawnY,
42:		})
